steps.rowTransform:
const year = (t.year || (t._info || '').match(/(19|20)\d{2}/) || [''])[0]
const info = (t._info || '').replace(/\s+/g, ' ')
const authors = info.split(/\s{2,}|\s-\s/)[0] || ''
return { title: t.title, url: t.url, abstract: t.abstract, authors, year, venue: info.slice(authors.length, authors.length + 60) }
